export type DetailRoute =
  | { kind: "search" }
  | { kind: "member"; id: string; view: "summary" | "history" }
  | { kind: "funder"; id: string }
  | { kind: "invalid" };

const funderIdPattern =
  /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu;
const memberIdPattern = /^[1-9]\d*$/u;

export function readDetailRoute(path: string): DetailRoute {
  if (path === "/") return { kind: "search" };
  const member = /^\/members\/([^/]+)(?:\/(history))?\/?$/u.exec(path);
  if (
    member &&
    memberIdPattern.test(member[1]) &&
    Number(member[1]) <= 2147483647
  )
    return {
      kind: "member",
      id: member[1],
      view: member[2] ? "history" : "summary",
    };
  const funder = /^\/funders\/([^/]+)\/?$/u.exec(path);
  if (funder && funderIdPattern.test(funder[1]))
    return { kind: "funder", id: funder[1] };
  return { kind: "invalid" };
}

export interface MemberProfile {
  id: string;
  name: string;
  partyName: string;
  membershipFrom: string;
  isCurrentCommons: boolean;
}

export interface FundingEntry {
  funder: { id: string; name: string } | null;
  amount: string | null;
  currency: string | null;
  paymentType: string | null;
}

export interface MemberDeclaration {
  sourceId: number;
  categoryId: number;
  categoryName: string;
  registeredAt: string | null;
  entries: FundingEntry[];
}

export interface MemberDetails {
  member: MemberProfile;
  declarations: MemberDeclaration[];
  summary: {
    currencies: (Total & {
      currency: string;
      categories: (Total & { categoryId: number; categoryName: string })[];
    })[];
    entryCount: number;
    unknownCurrencyCount: number;
    firstRegisteredAt: string | null;
    lastRegisteredAt: string | null;
    undatedDeclarationCount: number;
  };
}

interface Total {
  amount: string | null;
  entryCount: number;
  unknownAmountCount: number;
}

export interface FunderDetails {
  funder: {
    id: string;
    name: string;
    funderKind: string | null;
    companyNumber: string | null;
    aliases: string[];
  };
  currencies: {
    currency: string;
    parties: (Total & { partyName: string })[];
    topRecipients: (Total & { member: MemberProfile })[];
  }[];
  entryCount: number;
  unknownCurrencyCount: number;
  recipientLimit: number;
}

export type DetailState =
  | { kind: "loading" }
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
  | { kind: "error"; message: string };

function malformed(): never {
  throw new Error("Details returned an unexpected response. Try again.");
}
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function record(value: unknown): Record<string, unknown> {
  return isRecord(value) ? value : malformed();
}
function text(value: unknown): string {
  return typeof value === "string" ? value : malformed();
}
function nullableText(value: unknown): string | null {
  return value === null ? null : text(value);
}
function count(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : malformed();
}
function list(value: unknown): unknown[] {
  return Array.isArray(value) ? value : malformed();
}
function decimal(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !/^-?\d+(?:\.\d+)?$/u.test(result)) return malformed();
  return result;
}
function identity(value: unknown, kind: "MP" | "Funder"): string {
  const id = text(value);
  if (
    kind === "MP"
      ? !memberIdPattern.test(id) || Number(id) > 2147483647
      : !funderIdPattern.test(id)
  )
    return malformed();
  return id;
}
function memberProfile(value: unknown): MemberProfile {
  const row = record(value);
  if (typeof row.is_current_commons !== "boolean") return malformed();
  return {
    id: identity(row.id, "MP"),
    name: text(row.name),
    partyName: text(row.party_name),
    membershipFrom: text(row.membership_from),
    isCurrentCommons: row.is_current_commons,
  };
}
function integer(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value)
    ? value
    : malformed();
}
function timestamp(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !Number.isFinite(Date.parse(result)))
    return malformed();
  return result;
}
function declaration(value: unknown): MemberDeclaration {
  const row = record(value);
  return {
    sourceId: count(row.source_id),
    categoryId: integer(row.category_id),
    categoryName: text(row.category_name),
    registeredAt: timestamp(row.registered_at),
    entries: list(row.entries).map((value) => {
      const entry = record(value);
      const funder = entry.funder === null ? null : record(entry.funder);
      return {
        funder:
          funder === null
            ? null
            : { id: identity(funder.id, "Funder"), name: text(funder.name) },
        amount: decimal(entry.amount),
        currency: nullableText(entry.currency),
        paymentType: nullableText(entry.payment_type),
      };
    }),
  };
}
function readMember(value: unknown): MemberDetails {
  const row = record(value);
  const summary = record(row.summary);
  return {
    member: memberProfile(row.member),
    declarations: list(row.declarations).map(declaration),
    summary: {
      entryCount: count(summary.entry_count),
      unknownCurrencyCount: count(summary.unknown_currency_count),
      firstRegisteredAt: timestamp(summary.first_registered_at),
      lastRegisteredAt: timestamp(summary.last_registered_at),
      undatedDeclarationCount: count(summary.undated_declaration_count),
      currencies: list(summary.currencies).map((value) => {
        const group = record(value);
        const currency = text(group.currency);
        if (!currency.trim()) return malformed();
        return {
          ...total(group),
          currency,
          categories: list(group.categories).map((value) => {
            const category = record(value);
            return {
              ...total(category),
              categoryId: integer(category.category_id),
              categoryName: text(category.category_name),
            };
          }),
        };
      }),
    },
  };
}
function total(row: Record<string, unknown>): Total {
  return {
    amount: decimal(row.amount),
    entryCount: count(row.entry_count),
    unknownAmountCount: count(row.unknown_amount_count),
  };
}
function readFunder(value: unknown): FunderDetails {
  const row = record(value);
  const funder = record(row.funder);
  return {
    funder: {
      id: identity(funder.id, "Funder"),
      name: text(funder.name),
      funderKind: nullableText(funder.funder_kind),
      companyNumber: nullableText(funder.company_number),
      aliases: list(funder.aliases).map(text),
    },
    entryCount: count(row.entry_count),
    unknownCurrencyCount: count(row.unknown_currency_count),
    recipientLimit: count(row.recipient_limit),
    currencies: list(row.currencies).map((value) => {
      const group = record(value);
      const currency = text(group.currency);
      if (!currency.trim()) return malformed();
      return {
        currency,
        parties: list(group.parties).map((value) => {
          const party = record(value);
          return { ...total(party), partyName: text(party.party_name) };
        }),
        topRecipients: list(group.top_recipients).map((value) => {
          const recipient = record(value);
          return {
            ...total(recipient),
            member: memberProfile(recipient.member),
          };
        }),
      };
    }),
  };
}

export async function loadDetails(
  route: Extract<DetailRoute, { kind: "member" | "funder" }>,
  signal: AbortSignal,
): Promise<DetailState> {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, 10_000);
  try {
    const response = await fetch(
      `/api/${route.kind === "member" ? "members" : "funders"}/${route.id}`,
      { signal: controller.signal },
    );
    if (response.status === 404) return { kind: "not-found" };
    if (!response.ok)
      throw new Error(
        "The details service is unavailable. Try again in a moment.",
      );
    const body: unknown = await response.json();
    const state: DetailState =
      route.kind === "member"
        ? { kind: "member", details: readMember(body) }
        : { kind: "funder", details: readFunder(body) };
    if (
      (state.kind === "member"
        ? state.details.member.id
        : state.details.funder.id
      ).toLowerCase() !== route.id.toLowerCase()
    )
      return malformed();
    return state;
  } catch (error) {
    if (signal.aborted) throw error;
    return {
      kind: "error",
      message: timedOut
        ? "Details are taking too long. Try again."
        : error instanceof Error &&
            !(error instanceof TypeError || error instanceof SyntaxError)
          ? error.message
          : "Couldn’t connect to details. Check your connection and try again.",
    };
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", cancel);
  }
}

export function backToSearch(): string {
  const params = new URLSearchParams(window.location.search);
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  return retained.size ? `/?${retained}` : "/";
}

export function formatAmount(value: string | null): string {
  if (value === null) return "Amount unavailable";
  const negative = value.startsWith("-");
  const unsigned = negative ? value.slice(1) : value;
  const [whole, fraction] = unsigned.split(".");
  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
}

export function registrationDate(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}

export function memberHref(id: string, view: "summary" | "history"): string {
  const search = backToSearch().slice(1);
  return `/members/${id}${view === "history" ? "/history" : ""}${search}`;
}

export function categoryBars(
  categories: { amount: string | null }[],
): { width: number; negative: boolean }[] {
  const scale = Math.max(
    0,
    ...categories.map(({ amount }) => amount?.split(".")[1]?.length ?? 0),
  );
  const values = categories.map(({ amount }) => {
    if (amount === null) return 0n;
    const [whole, fraction = ""] = amount.replace(/^-/, "").split(".");
    const value = BigInt(whole + fraction.padEnd(scale, "0"));
    return amount.startsWith("-") ? -value : value;
  });
  const maximum = values.reduce((largest, value) => {
    const magnitude = value < 0n ? -value : value;
    return magnitude > largest ? magnitude : largest;
  }, 0n);
  return values.map((value) => ({
    negative: value < 0n,
    width:
      maximum === 0n
        ? 0
        : Number(((value < 0n ? -value : value) * 10000n) / maximum) / 100,
  }));
}
//! Stored profiles, declaration occurrences, and exact currency summaries.

use bigdecimal::BigDecimal;
use chrono::{DateTime, Utc};

use super::{
    funder::{Funder, FunderId},
    parliament_member::MemberId,
};

/// Latest stored member profile, not membership at the time of a payment.
#[derive(Clone, Debug)]
pub struct MemberProfile {
    /// Parliament identity.
    pub id: MemberId,
    /// Source name.
    pub name: String,
    /// Latest recorded party identity.
    pub party_id: i32,
    /// Latest recorded party name.
    pub party_name: String,
    /// Latest membership description, including constituencies and Lords memberships.
    pub membership_from: String,
    /// Current Commons membership.
    pub is_current_commons: bool,
}

/// A named funder on a declaration.
#[derive(Clone, Debug)]
pub struct FunderReference {
    /// Persistent identity.
    pub id: FunderId,
    /// Exact source name.
    pub name: String,
}

/// One source funding occurrence, including incomplete values.
#[derive(Clone, Debug)]
pub struct DeclaredFunding {
    /// Named funder when available.
    pub funder: Option<FunderReference>,
    /// Exact source amount.
    pub amount: Option<BigDecimal>,
    /// Normalized source currency, absent when unknown.
    pub currency: Option<String>,
    /// Source payment classification.
    pub payment_type: Option<String>,
}

/// A declaration with all of its funding occurrences.
#[derive(Clone, Debug)]
pub struct MemberDeclaration {
    /// Parliament declaration identity.
    pub source_id: i32,
    /// Canonical source category classification.
    pub category: DeclarationCategory,
    /// Source category.
    pub category_name: String,
    /// Registration date when available.
    pub registered_at: Option<DateTime<Utc>>,
    /// Funding occurrences, preserving duplicates.
    pub entries: Vec<DeclaredFunding>,
}

/// Canonical classification preserves unrecognized source categories.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
pub enum DeclarationCategory {
    /// Donations and other support, including loans.
    DonationSupport,
    /// Any other category, retaining its source identity.
    Other(i32),
}
impl DeclarationCategory {
    /// Decodes the source vocabulary without guessing from labels.
    #[must_use]
    pub const fn from_source_id(id: i32) -> Self {
        match id {
            3 => Self::DonationSupport,
            other => Self::Other(other),
        }
    }
    /// Whether the category records donations and other support.
    #[must_use]
    pub const fn is_donation_support(self) -> bool {
        match self {
            Self::DonationSupport => true,
            Self::Other(_) => false,
        }
    }
    /// Encodes the original source identity.
    #[must_use]
    pub const fn source_id(self) -> i32 {
        match self {
            Self::DonationSupport => 3,
            Self::Other(id) => id,
        }
    }
}

/// Complete consistent repository input.
#[derive(Clone, Debug)]
pub struct MemberHistory {
    /// Latest member profile.
    pub member: MemberProfile,
    /// All declarations in registration order.
    pub declarations: Vec<MemberDeclaration>,
}

/// Exact amounts and coverage for one category and currency.
#[derive(Clone, Debug)]
pub struct CategoryTotal {
    /// Source identity.
    pub category: DeclarationCategory,
    /// Original category label.
    pub category_name: String,
    /// Known amounts, unavailable when no amount is known.
    pub amount: Option<BigDecimal>,
    /// Funding occurrences.
    pub entry_count: usize,
    /// Occurrences without an amount.
    pub unknown_amount_count: usize,
}

/// Independent amounts for a known currency.
#[derive(Clone, Debug)]
pub struct MemberCurrencyTotal {
    /// Normalized source currency.
    pub currency: String,
    /// Exact total, including zero and negative amounts.
    pub amount: Option<BigDecimal>,
    /// Funding occurrences.
    pub entry_count: usize,
    /// Occurrences without an amount.
    pub unknown_amount_count: usize,
    /// All represented categories.
    pub categories: Vec<CategoryTotal>,
}

/// Coverage and exact totals across complete stored history.
#[derive(Clone, Debug)]
pub struct MemberSummary {
    /// Separate currencies without conversion.
    pub currencies: Vec<MemberCurrencyTotal>,
    /// All funding occurrences.
    pub entry_count: usize,
    /// Occurrences whose currency is unknown.
    pub unknown_currency_count: usize,
    /// Earliest known registration timestamp.
    pub first_registered_at: Option<DateTime<Utc>>,
    /// Latest known registration timestamp.
    pub last_registered_at: Option<DateTime<Utc>>,
    /// Declarations without a registration timestamp.
    pub undated_declaration_count: usize,
}

/// Member summary and complete history from one consistent read.
#[derive(Clone, Debug)]
pub struct MemberDetails {
    /// Latest profile.
    pub member: MemberProfile,
    /// Complete ordered declarations.
    pub declarations: Vec<MemberDeclaration>,
    /// Exact complete-history totals.
    pub summary: MemberSummary,
}

/// Canonical funder profile with recorded names.
#[derive(Clone, Debug)]
pub struct FunderProfile {
    /// Persistent funder.
    pub funder: Funder,
    /// Company identifier with leading zeros intact.
    pub company_number: Option<String>,
    /// Every stored exact name, in stable order.
    pub aliases: Vec<String>,
}

/// Compact repository aggregate for one recipient and currency.
#[derive(Clone, Debug)]
pub struct RecipientAllocation {
    /// Latest stored recipient profile.
    pub member: MemberProfile,
    /// Source currency when recorded; unknown currencies never have totals.
    pub currency: Option<String>,
    /// Sum of known amounts, or unavailable if none are known.
    pub known_total: Option<BigDecimal>,
    /// All source occurrences.
    pub entry_count: i64,
    /// Occurrences with missing amounts.
    pub unknown_amount_count: i64,
}

/// Repository input for a consistent funder summary.
#[derive(Clone, Debug)]
pub struct FunderFunding {
    /// Persistent funder identity.
    pub profile: FunderProfile,
    /// One row per recipient and currency.
    pub allocations: Vec<RecipientAllocation>,
}

/// Support grouped by recipients' latest stored party.
#[derive(Clone, Debug)]
pub struct PartyTotal {
    /// Latest stored party identity.
    pub party_id: i32,
    /// Latest stored party name.
    pub party_name: String,
    /// Total of known amounts only.
    pub amount: Option<BigDecimal>,
    /// Funding occurrences.
    pub entry_count: i64,
    /// Occurrences with unknown amounts.
    pub unknown_amount_count: i64,
}

/// Independent totals and rankings for a single currency.
#[derive(Clone, Debug)]
pub struct CurrencyBreakdown {
    /// Source currency.
    pub currency: String,
    /// All recorded party totals.
    pub parties: Vec<PartyTotal>,
    /// Highest known totals, followed by unavailable totals if space remains.
    pub top_recipients: Vec<RecipientAllocation>,
}

/// Funder summary without currency conversion or historical party inference.
#[derive(Clone, Debug)]
pub struct FunderDetails {
    /// Persistent funder identity.
    pub profile: FunderProfile,
    /// Summaries for each known currency.
    pub currencies: Vec<CurrencyBreakdown>,
    /// All funding occurrences.
    pub entry_count: i64,
    /// Occurrences excluded because currency is unknown.
    pub unknown_currency_count: i64,
    /// Maximum recipients per currency.
    pub recipient_limit: usize,
}
//! Entity profiles and summaries from a shared exact aggregate.

mod interface;
pub use interface::EntityDetailsService;

use crate::domain::{
    models::{
        entity_details::{
            CategoryTotal, CurrencyBreakdown, DeclarationCategory, FunderDetails, FunderFunding,
            MemberCurrencyTotal, MemberDetails, MemberHistory, MemberSummary, PartyTotal,
            RecipientAllocation,
        },
        funder::FunderId,
        parliament_member::MemberId,
    },
    repositories::entity_details::{EntityDetailsRepo, EntityDetailsRepoError},
};
use std::{cmp::Ordering, collections::BTreeMap};
use thiserror::Error;

const TOP_RECIPIENTS: usize = 10;

/// Entity detail lookup failure.
#[derive(Debug, Error)]
pub enum EntityDetailsError {
    /// No stored identity matches the request.
    #[error("entity not found")]
    NotFound,
    /// Private database diagnostics.
    #[error(transparent)]
    Unexpected(#[from] EntityDetailsRepoError),
}

/// Detail service owns summary rules and presentation limits.
#[derive(Clone)]
pub struct Service<R> {
    repo: R,
}

impl<R> Service<R> {
    /// Creates a detail service.
    #[must_use]
    pub const fn new(repo: R) -> Self {
        Self { repo }
    }
}

impl<R: EntityDetailsRepo> EntityDetailsService for Service<R> {
    async fn member(&self, id: MemberId) -> Result<MemberDetails, EntityDetailsError> {
        self.repo
            .member(id)
            .await?
            .map(summarize_member)
            .ok_or(EntityDetailsError::NotFound)
    }
    async fn funder(&self, id: FunderId) -> Result<FunderDetails, EntityDetailsError> {
        self.repo
            .funder_funding(id)
            .await?
            .map(summarize_funder)
            .ok_or(EntityDetailsError::NotFound)
    }
}

fn add_known(total: &mut Option<bigdecimal::BigDecimal>, amount: Option<&bigdecimal::BigDecimal>) {
    if let Some(amount) = amount {
        match total {
            Some(total) => *total += amount,
            None => *total = Some(amount.clone()),
        }
    }
}

fn summarize_member(history: MemberHistory) -> MemberDetails {
    let mut currencies: BTreeMap<String, MemberCurrencyTotal> = BTreeMap::new();
    let mut categories: BTreeMap<(String, DeclarationCategory, String), CategoryTotal> =
        BTreeMap::new();
    let mut summary = MemberSummary {
        currencies: Vec::new(),
        entry_count: 0,
        unknown_currency_count: 0,
        first_registered_at: None,
        last_registered_at: None,
        undated_declaration_count: 0,
    };
    for declaration in &history.declarations {
        if let Some(date) = declaration.registered_at {
            summary.first_registered_at = Some(
                summary
                    .first_registered_at
                    .map_or(date, |first| first.min(date)),
            );
            summary.last_registered_at = Some(
                summary
                    .last_registered_at
                    .map_or(date, |last| last.max(date)),
            );
        } else {
            summary.undated_declaration_count += 1;
        }
        for entry in &declaration.entries {
            summary.entry_count += 1;
            let Some(currency) = &entry.currency else {
                summary.unknown_currency_count += 1;
                continue;
            };
            let group = currencies
                .entry(currency.clone())
                .or_insert_with(|| MemberCurrencyTotal {
                    currency: currency.clone(),
                    amount: None,
                    entry_count: 0,
                    unknown_amount_count: 0,
                    categories: Vec::new(),
                });
            add_known(&mut group.amount, entry.amount.as_ref());
            group.entry_count += 1;
            group.unknown_amount_count += usize::from(entry.amount.is_none());
            let category = categories
                .entry((
                    currency.clone(),
                    declaration.category,
                    declaration.category_name.clone(),
                ))
                .or_insert_with(|| CategoryTotal {
                    category: declaration.category,
                    category_name: declaration.category_name.clone(),
                    amount: None,
                    entry_count: 0,
                    unknown_amount_count: 0,
                });
            add_known(&mut category.amount, entry.amount.as_ref());
            category.entry_count += 1;
            category.unknown_amount_count += usize::from(entry.amount.is_none());
        }
    }
    for ((currency, _, _), category) in categories {
        if let Some(group) = currencies.get_mut(&currency) {
            group.categories.push(category);
        }
    }
    summary.currencies = currencies.into_values().collect();
    MemberDetails {
        member: history.member,
        declarations: history.declarations,
        summary,
    }
}

fn compare_allocations(left: &RecipientAllocation, right: &RecipientAllocation) -> Ordering {
    right
        .known_total
        .cmp(&left.known_total)
        .then_with(|| left.member.id.value().cmp(&right.member.id.value()))
        .then_with(|| left.member.name.cmp(&right.member.name))
}

fn summarize_funder(funding: FunderFunding) -> FunderDetails {
    let mut entry_count = 0;
    let mut unknown_currency_count = 0;
    let mut currencies: BTreeMap<String, Vec<RecipientAllocation>> = BTreeMap::new();
    for allocation in funding.allocations {
        entry_count += allocation.entry_count;
        if let Some(currency) = &allocation.currency {
            currencies
                .entry(currency.clone())
                .or_default()
                .push(allocation);
        } else {
            unknown_currency_count += allocation.entry_count;
        }
    }
    let currencies = currencies
        .into_iter()
        .map(|(currency, mut allocations)| {
            let mut parties: BTreeMap<(i32, String), PartyTotal> = BTreeMap::new();
            for allocation in &allocations {
                let party = parties
                    .entry((
                        allocation.member.party_id,
                        allocation.member.party_name.clone(),
                    ))
                    .or_insert_with(|| PartyTotal {
                        party_id: allocation.member.party_id,
                        party_name: allocation.member.party_name.clone(),
                        amount: None,
                        entry_count: 0,
                        unknown_amount_count: 0,
                    });
                if let Some(amount) = &allocation.known_total {
                    if let Some(total) = &mut party.amount {
                        *total += amount;
                    } else {
                        party.amount = Some(amount.clone());
                    }
                }
                party.entry_count += allocation.entry_count;
                party.unknown_amount_count += allocation.unknown_amount_count;
            }
            let mut parties: Vec<_> = parties.into_values().collect();
            parties.sort_by(|left, right| {
                right
                    .amount
                    .cmp(&left.amount)
                    .then_with(|| left.party_name.cmp(&right.party_name))
                    .then_with(|| left.party_id.cmp(&right.party_id))
            });
            allocations.sort_by(compare_allocations);
            allocations.truncate(TOP_RECIPIENTS);
            CurrencyBreakdown {
                currency,
                parties,
                top_recipients: allocations,
            }
        })
        .collect();
    FunderDetails {
        profile: funding.profile,
        currencies,
        entry_count,
        unknown_currency_count,
        recipient_limit: TOP_RECIPIENTS,
    }
}
